package main

import (
	"context"
	"errors"
)

func runPipeline(ctx context.Context, capacity int, produce func(context.Context, chan<- int) error, consume func(context.Context, <-chan int) error) error {
	out := make(chan int, capacity)
	done := make(chan error, 1)
	go func() { defer close(out); done <- produce(ctx, out) }()
	consumerErr := consume(ctx, out)
	return errors.Join(consumerErr, <-done)
}
package main

import (
	"bufio"
	"context"
	"flag"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

func command(ctx context.Context, args []string, input io.Reader, output, diagnostic io.Writer) int {
	flags := flag.NewFlagSet("pipeline", flag.ContinueOnError)
	flags.SetOutput(diagnostic)
	take := flags.Int("take", 1000000, "maximum accepted integers")
	if err := flags.Parse(args); err != nil || *take <= 0 || flags.NArg() != 0 {
		return 2
	}
	err := runPipeline(ctx, 1, func(ctx context.Context, out chan<- int) error {
		scanner := bufio.NewScanner(input)
		for scanner.Scan() {
			value, err := strconv.Atoi(strings.TrimSpace(scanner.Text()))
			if err != nil {
				return fmt.Errorf("integer input: %w", err)
			}
			select {
			case out <- value:
			case <-ctx.Done():
				return ctx.Err()
			}
		}
		return scanner.Err()
	}, func(ctx context.Context, in <-chan int) error {
		for accepted := 0; accepted < *take; accepted++ {
			select {
			case value, ok := <-in:
				if !ok {
					return nil
				}
				if _, err := fmt.Fprintln(output, value); err != nil {
					return err
				}
			case <-ctx.Done():
				return ctx.Err()
			}
		}
		return nil
	})
	if err != nil {
		fmt.Fprintln(diagnostic, err)
		return 2
	}
	return 0
}
func main() { os.Exit(command(context.Background(), os.Args[1:], os.Stdin, os.Stdout, os.Stderr)) }
package main

import (
	"context"
	"reflect"
	"testing"
)

func TestFinitePipeline(t *testing.T) {
	var got []int
	err := runPipeline(context.Background(), 1, func(ctx context.Context, out chan<- int) error {
		for _, v := range []int{1, 2} {
			select {
			case out <- v:
			case <-ctx.Done():
				return ctx.Err()
			}
		}
		return nil
	}, func(ctx context.Context, in <-chan int) error {
		for v := range in {
			got = append(got, v)
		}
		return nil
	})
	if err != nil || !reflect.DeepEqual(got, []int{1, 2}) {
		t.Fatalf("got=%v err=%v", got, err)
	}
}

package main

import (
	"context"
	"errors"
)

func runPipeline(ctx context.Context, capacity int, produce func(context.Context, chan<- int) error, consume func(context.Context, <-chan int) error) error {
	out := make(chan int, capacity)
	workCtx, cancel := context.WithCancel(ctx)
	type result struct {
		producer bool
		err      error
	}
	results := make(chan result, 2)
	go func() {
		defer close(out)
		err := produce(workCtx, out)
		results <- result{producer: true, err: err}
	}()
	go func() { results <- result{err: consume(workCtx, out)} }()

	var producerErr, consumerErr error
	producerDone, consumerDone := false, false
	suppressProducerStop, suppressConsumerStop := false, false
	callerDone := ctx.Done()
	for !producerDone || !consumerDone {
		select {
		case <-callerDone:
			callerDone = nil
			cancel()
		case r := <-results:
			if r.producer {
				producerDone, producerErr = true, r.err
				if r.err != nil {
					suppressConsumerStop = true
					cancel()
				}
			} else {
				consumerDone, consumerErr = true, r.err
				suppressProducerStop = true
				cancel()
			}
		}
	}
	cancel()

	var errs []error
	for i, err := range []error{producerErr, consumerErr} {
		if err == nil {
			continue
		}
		suppress := (i == 0 && suppressProducerStop) || (i == 1 && suppressConsumerStop)
		if ctx.Err() == nil && suppress && (err == context.Canceled || err == context.DeadlineExceeded) {
			continue
		}
		errs = append(errs, err)
	}
	if err := ctx.Err(); err != nil {
		errs = append(errs, err)
	}
	return errors.Join(errs...)
}
